"""I/O for `newsrag editions`: folio records from the ledger, `editions.yaml`, `page_editions`."""

from __future__ import annotations

import datetime as dt
import io
import json
from pathlib import Path
from typing import Any

from newsrag.config import settings
from newsrag.editions import mapping

HEADER = (
    "# Edition code -> edition name, per year (ticket 011). Generated by\n"
    "# `uv run newsrag editions build` from the folio printed on each page. Keys a person adds to\n"
    "# an entry (e.g. name_en) are kept on rebuild; the generated keys are rewritten.\n"
)


def folio_records() -> list[dict[str, Any]]:
    """One record per page whose `folio` stage is done (see `mapping`)."""
    from newsrag.ledger import db

    with db.conn() as c:
        rows = db.fetch_all(
            c,
            "select p.page_id, p.pub_date, p.edition_code, p.section, s.artifact_path "
            "from stage_runs s join pages p using (page_id) "
            "where s.stage = 'folio' and s.status = 'done' order by p.page_id",
        )
    records = []
    for row in rows:
        path = Path(row["artifact_path"] or "")
        if not path.is_file():
            raise FileNotFoundError(f"folio artifact missing for {row['page_id']}: {path}")
        art = json.loads(path.read_text(encoding="utf-8"))
        records.append(
            {
                "page_id": row["page_id"],
                "pub_date": row["pub_date"],
                "edition_code": row["edition_code"],
                "section": row["section"],
                "place_te": art.get("place_te"),
                "place_districts_current": art.get("place_districts_current"),
                "place_districts_at_print": art.get("place_districts_at_print"),
                "place_state": art.get("place_state"),
                "printed_date": art.get("printed_date"),
            }
        )
    return records


# --- editions.yaml --------------------------------------------------------------------------------


def _yaml():
    from ruamel.yaml import YAML

    y = YAML()
    y.preserve_quotes = True
    y.width = 200
    y.indent(mapping=2, sequence=4, offset=2)
    return y


def load_editions(path: Path | None = None) -> Any:
    """The map as stored ({} when the file is missing), as a ruamel round-trip mapping."""
    from ruamel.yaml.comments import CommentedMap

    path = Path(path or settings.editions_file)
    if not path.is_file():
        return CommentedMap()
    data = _yaml().load(path.read_text(encoding="utf-8"))
    return data if data is not None else CommentedMap()


def as_plain(data: Any) -> dict[int, dict[str, dict[str, Any]]]:
    out: dict[int, dict[str, dict[str, Any]]] = {}
    for year, codes in (data or {}).items():
        out[int(year)] = {str(code): dict(entry or {}) for code, entry in (codes or {}).items()}
    return out


def _flow(values: list[str]) -> Any:
    from ruamel.yaml.comments import CommentedSeq

    seq = CommentedSeq(values)
    seq.fa.set_flow_style()
    return seq


def write_editions(built: dict[int, dict[str, dict[str, Any]]], path: Path | None = None) -> Path:
    """Merge `built` into the stored map (hand-added keys kept) and write it."""
    from ruamel.yaml.comments import CommentedMap

    path = Path(path or settings.editions_file)
    data = load_editions(path)
    # Codes no longer built lose their generated keys; an entry left empty is dropped.
    for ykey in list(data):
        year_map = data[ykey] or {}
        for code in list(year_map):
            if code in built.get(int(ykey), {}):
                continue
            entry = year_map[code] or {}
            for k in mapping.GENERATED_KEYS:
                entry.pop(k, None)
            if not entry:
                del year_map[code]
        if not year_map:
            del data[ykey]
    for year, codes in built.items():
        key = next((k for k in data if int(k) == year), year)
        year_map = data.get(key)
        if year_map is None:
            year_map = CommentedMap()
            data[key] = year_map
        for code, entry in codes.items():
            old = year_map.get(code)
            merged = CommentedMap()
            for k, v in mapping.merge_entry(dict(old or {}), entry).items():
                merged[k] = _flow(list(v)) if isinstance(v, list) else v
            year_map[code] = merged  # generated keys first, then the hand-added ones
        # codes in sorted order
        for code in sorted(year_map):
            year_map.move_to_end(code)
    for k in sorted(data, key=int):
        data.move_to_end(k)
    path.parent.mkdir(parents=True, exist_ok=True)
    buf = io.StringIO()
    _yaml().dump(data, buf)
    # the loaded file's own header comes back with the data: write HEADER once
    lines = buf.getvalue().splitlines(keepends=True)
    while lines and lines[0].startswith("#"):
        lines.pop(0)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(HEADER + "".join(lines), encoding="utf-8")
    tmp.replace(path)
    return path


def build(path: Path | None = None) -> tuple[Path, dict[int, dict[str, dict[str, Any]]]]:
    built = mapping.build_map(
        folio_records(),
        settings.editions_min_agreement,
        settings.editions_min_pages,
        settings.editions_state_sections,
    )
    return write_editions(built, path), built


# --- page_editions --------------------------------------------------------------------------------


def apply(path: Path | None = None) -> int:
    """Replace `page_editions` (one transaction) with one row per page whose folio is done."""
    from newsrag.ledger import db

    editions = as_plain(load_editions(path))
    sections = settings.editions_state_sections
    records = folio_records()
    code_states = mapping.state_page_states(records, sections)
    rows = [
        mapping.page_edition(
            r,
            editions.get(r["pub_date"].year, {}),
            sections,
            code_states.get((r["pub_date"].year, r["edition_code"])),
        )
        for r in records
    ]
    with db.conn() as c:
        c.execute("delete from page_editions")
        with c.cursor() as cur:
            cur.executemany(
                "insert into page_editions (page_id, edition_names, districts_current, "
                "districts_at_print, states, source, flags) values (%s, %s, %s, %s, %s, %s, %s)",
                [
                    (
                        pe.page_id,
                        pe.edition_names,
                        pe.districts_current,
                        pe.districts_at_print,
                        pe.states,
                        pe.source,
                        pe.flags,
                    )
                    for pe in rows
                ],
            )
    return len(rows)


def report(path: Path | None = None) -> list[str]:
    from newsrag.ledger import db

    editions = as_plain(load_editions(path))
    with db.conn() as c:
        pages = db.fetch_all(
            c,
            "select p.pub_date, p.edition_code, e.flags "
            "from page_editions e join pages p using (page_id)",
        )
    triples: list[tuple[dt.date, str, list[str]]] = [
        (r["pub_date"], r["edition_code"], list(r["flags"] or [])) for r in pages
    ]
    return mapping.report_lines(
        editions, triples, folio_records(), settings.editions_state_sections
    )
